from fastapi import FastAPI, Depends
from fastapi.security import OAuth2PasswordBearer

app = FastAPI()
oauth2 = OAuth2PasswordBearer(tokenUrl="/token", auto_error=False)

@app.get("/items/")
async def read_items(token: str | None = Depends(oauth2)):
    if token is None:
        return {"auth": False}
    return {"auth": True}

